"""NRS 484B.307(5)(a) straight-arrow controller and source guards.

CARLA's generic green state does not identify an arrow indication. Native
capture must supply a verified signal-head description before any attempt.
"""
import argparse
import json
import math
from pathlib import Path

ROOT=Path(__file__).resolve().parent


def load_scene(path=None):
    scene=json.loads(Path(path or ROOT/'scene.json').read_text())
    if (scene['law_id'],scene['cell_id'],scene['actor']) != (
            'NRS-484B-307-5a','C111125','motor_vehicle_driver'):
        raise ValueError('wrong frozen assignment identity')
    if scene['approach_x_m']>=scene['stop_line_x_m'] or scene['exit_x_m']<=scene['intersection_x_max_m']:
        raise ValueError('straight route must approach stop line and clear intersection')
    if scene['intersection_x_min_m']>=scene['intersection_x_max_m']:
        raise ValueError('invalid intersection bounds')
    if not (0<scene['arrow_exhibition_after_s']<scene['duration_s']):
        raise ValueError('arrow exhibition schedule outside capture')
    return scene


def require_sole_straight_arrow(signal, *, head_id, frame):
    """Read back one source-verified facing head; reject a generic green bulb."""
    if signal.get('source_verified') is not True or not signal.get('source_ref'):
        raise ValueError('sole arrow lacks source-verified signal head')
    if signal.get('head_id')!=head_id or signal.get('observed_frame')!=frame:
        raise ValueError('signal aspect is not bound to the facing head and frame')
    indications=signal.get('illuminated_indications')
    if indications!=[{'color':'green','shape':'arrow','direction':'straight'}]:
        raise ValueError('facing signal is not a sole green straight-through arrow')
    return signal


def select_facing_head(scene, heads, *, frame):
    """Select a source-verified facing arrow head by a predeclared slot.

    The alternate slot is engineering redundancy, never an outcome selector.
    A Native adapter must populate heads from original per-frame signal sources.
    """
    slot=scene.get('candidate_head_slot',0)
    if type(slot) is not int or slot<0:
        raise ValueError('invalid predeclared head slot')
    facing=[head for head in heads if head.get('faces_ego_approach') is True]
    if any(type(head.get('head_id')) is not int for head in facing):
        raise ValueError('facing signal head lacks stable integer ID')
    facing.sort(key=lambda head:head['head_id'])
    if len({head['head_id'] for head in facing})!=len(facing):
        raise ValueError('duplicate facing signal head ID')
    if slot>=len(facing):
        raise ValueError('selected facing signal head slot absent')
    chosen=facing[slot]
    return require_sole_straight_arrow(chosen,head_id=chosen['head_id'],frame=frame)


def body_bounds(vertices):
    if not isinstance(vertices,list) or len(vertices)<4 or any(
            not isinstance(v,list) or len(v)<2 or
            any(type(x) not in (int,float) or not math.isfinite(x) for x in v[:2])
            for v in vertices):
        raise ValueError('missing finite participant body footprint')
    return (min(v[0] for v in vertices),min(v[1] for v in vertices),
            max(v[0] for v in vertices),max(v[1] for v in vertices))


def overlaps(vertices,region):
    left,bottom,right,top=body_bounds(vertices)
    if len(region)!=4 or any(type(x) not in (int,float) or not math.isfinite(x) for x in region):
        raise ValueError('invalid intersection or crosswalk bounds')
    a,b,c,d=region
    if a>=c or b>=d:raise ValueError('invalid region bounds')
    return left<=c and right>=a and bottom<=d and top>=b


def yield_decision(scene, participants, *, signal_exhibited_frame, current_frame):
    """Hold at the line while a lawfully present participant still occupies it.

    Lawful presence is an independently sourced input, never inferred from a
    pedestrian's or vehicle's position alone.
    """
    if current_frame<signal_exhibited_frame:raise ValueError('signal exhibition time is in the future')
    occupied=[]
    regions=[scene['intersection_bounds_m'],*scene['adjacent_crosswalk_bounds_m']]
    for item in participants:
        if not {'id','role','body_vertices_m','lawful_presence_source','lawfully_present'}<=item.keys():
            raise ValueError('participant lawfulness or body source missing')
        if item['role'] not in ('vehicle','pedestrian'):
            raise ValueError('unsupported participant role')
        body_bounds(item['body_vertices_m'])
        within=any(overlaps(item['body_vertices_m'],r) for r in regions)
        if within and (type(item['lawfully_present']) is not bool or not item['lawful_presence_source']):
            raise ValueError('lawful presence source missing for governed-region occupant')
        if within and item['lawfully_present']:
            occupied.append(item['id'])
    return {'hold_at_stop_line':bool(occupied),'occupied_by':occupied,
            'signal_exhibited_frame':signal_exhibited_frame,'decision_frame':current_frame,
            'method':'original participant body overlap and independently sourced lawful presence'}


def command(scene, ego_front_x_m, decision):
    if not isinstance(decision,dict) or 'hold_at_stop_line' not in decision:
        raise ValueError('missing yield decision')
    if decision['hold_at_stop_line'] and ego_front_x_m>scene['stop_line_x_m']:
        raise ValueError('ego already crossed stop line before yield cleared')
    return {'throttle':0.0 if decision['hold_at_stop_line'] else .25,
            'brake':1.0 if decision['hold_at_stop_line'] else 0.0,
            'steer':0.0,'intended_maneuver':'straight'}


def control_step(scene, signal, participants, ego_vertices, *, first_arrow_frame=None,
                 exhibition_occupants=None):
    """Decide the next Native control from the latest original frame.

    Unknown source facts fail closed. The initial control is a full brake until
    the first observed frame is available; this decision controls the next tick.
    """
    frame=signal.get('frame')
    if type(frame) is not int:
        raise ValueError('original signal frame missing')
    hold={'throttle':0.0,'brake':1.0,'steer':0.0,'intended_maneuver':'straight'}
    try:
        require_sole_straight_arrow(signal['aspect'],
                                   head_id=signal['facing_head_id'],frame=frame)
    except (KeyError,ValueError) as exc:
        return {'control':hold,'reason':'unverified_sole_arrow',
                'source_error':str(exc),'first_arrow_frame':first_arrow_frame,
                'exhibition_occupants':exhibition_occupants}
    if first_arrow_frame is None:
        first_arrow_frame=frame
        try:
            first=yield_decision(scene,participants,
                                 signal_exhibited_frame=frame,current_frame=frame)
            exhibition_occupants=first['occupied_by']
        except ValueError as exc:
            return {'control':hold,'reason':'unverified_exhibition_lawfulness',
                    'source_error':str(exc),'first_arrow_frame':frame,
                    'exhibition_occupants':None}
    if exhibition_occupants is None:
        return {'control':hold,'reason':'unverified_exhibition_lawfulness',
                'source_error':'lawful presence at original exhibition frame was unverified',
                'first_arrow_frame':first_arrow_frame,'exhibition_occupants':None}
    regions=[scene['intersection_bounds_m'],*scene['adjacent_crosswalk_bounds_m']]
    occupants={item['id']:item for item in participants}
    missing=[ident for ident in exhibition_occupants if ident not in occupants]
    if missing:
        return {'control':hold,'reason':'missing_exhibition_occupant_body',
                'source_error':'original body no longer available: '+str(missing),
                'first_arrow_frame':first_arrow_frame,
                'exhibition_occupants':exhibition_occupants}
    try:
        remaining=[ident for ident in exhibition_occupants if any(
            overlaps(occupants[ident]['body_vertices_m'],region) for region in regions)]
        front=body_bounds(ego_vertices)[2]
        control=command(scene,front,{'hold_at_stop_line':bool(remaining)})
    except ValueError as exc:
        return {'control':hold,'reason':'unverified_lawful_presence_or_geometry',
                'source_error':str(exc),'first_arrow_frame':first_arrow_frame,
                'exhibition_occupants':exhibition_occupants}
    return {'control':control,'reason':'yield_hold' if remaining else 'straight_clear',
            'occupied_by':remaining,'first_arrow_frame':first_arrow_frame,
            'exhibition_occupants':exhibition_occupants}


def spawn_scene(world,scene,transform_factory):
    """Create distinct ego, vehicle and pedestrian actors for the exact case.

    The occupied case starts both participants outside the governed regions, so
    original capture can observe their entry before arrow exhibition.
    """
    library=world.get_blueprint_library()
    specs=[('ego','vehicle.*',scene['approach_x_m'],0,0),
           ('vehicle','vehicle.*',0 if scene['participant_occupancy_setup']=='lawfully_present' else 35,
            -12 if scene['participant_occupancy_setup']=='lawfully_present' else 0,90),
           ('pedestrian','walker.pedestrian.*',9 if scene['participant_occupancy_setup']=='lawfully_present' else 35,
            -9 if scene['participant_occupancy_setup']=='lawfully_present' else 0,90)]
    if scene['participant_occupancy_setup'] not in ('clear','lawfully_present'):
        raise ValueError('unsupported occupancy setup')
    actors={}
    try:
        for name,pattern,x,y,yaw in specs:
            matches=list(library.filter(pattern))
            if not matches:raise ValueError('missing Native actor blueprint: '+pattern)
            actors[name]=world.spawn_actor(matches[0],transform_factory(x,y,0,yaw))
        if len({id(actor) for actor in actors.values()})!=len(actors):
            raise ValueError('Native world reused an actor for distinct roles')
    except BaseException:
        for actor in reversed(list(actors.values())):
            if hasattr(actor,'destroy'):actor.destroy()
        raise
    return actors


def authored_arrow_state(scene,elapsed_s):
    """Predeclared Red-to-Green stimulus; original readback controls inference."""
    if type(elapsed_s) not in (int,float) or not math.isfinite(elapsed_s) or elapsed_s<0:
        raise ValueError('invalid arrow schedule time')
    return 'Red' if elapsed_s<scene['arrow_exhibition_after_s'] else 'Green'


def participant_motion(scene, elapsed_s):
    """Native control targets that clear both governed regions after a hold.

    The vehicle crosses northbound through the intersection; the pedestrian
    crosses the adjacent crosswalk. This is a construction policy only. Body
    positions and lawful presence must still be read back from original sources.
    """
    if type(elapsed_s) not in (int,float) or not math.isfinite(elapsed_s) or elapsed_s<0:
        raise ValueError('invalid participant elapsed time')
    if scene['participant_occupancy_setup']=='clear':
        return {'vehicle_velocity_xyz_mps':(0.,0.,0.),
                'pedestrian_direction_xyz':(0.,0.,0.),'pedestrian_speed_mps':0.}
    if scene['participant_occupancy_setup']!='lawfully_present':
        raise ValueError('unsupported occupancy setup')
    # The target motion moves bodies beyond the y=5 m region boundary within
    # the 30 s capture. A Native controller must stop them after readback clears.
    return {'vehicle_velocity_xyz_mps':(0.,2.,0.),
            'pedestrian_direction_xyz':(0.,1.,0.),'pedestrian_speed_mps':1.5}


def apply_participant_motion(scene, actors, carla, elapsed_s):
    """Issue the occupied/clear construction controls to owned Native actors."""
    motion=participant_motion(scene,elapsed_s)
    vx,vy,vz=motion['vehicle_velocity_xyz_mps']
    dx,dy,dz=motion['pedestrian_direction_xyz']
    actors['vehicle'].set_target_velocity(carla.Vector3D(x=vx,y=vy,z=vz))
    actors['pedestrian'].apply_control(carla.WalkerControl(
        direction=carla.Vector3D(x=dx,y=dy,z=dz),speed=motion['pedestrian_speed_mps']))
    return motion


def check():
    scene=load_scene()
    assert scene['approach_x_m']<scene['stop_line_x_m']<scene['intersection_x_max_m']<scene['exit_x_m']
    heads=[{'source_verified':True,'source_ref':'synthetic/check-only',
            'head_id':head_id,'observed_frame':0,'faces_ego_approach':True,
            'illuminated_indications':[{'color':'green','shape':'arrow','direction':'straight'}]}
           for head_id in (7,8)]
    chosen=select_facing_head(scene,heads,frame=0)
    print(json.dumps({'geometry_checked':True,'selected_synthetic_head_id':chosen['head_id'],
                      'sole_arrow_source_verification_pending':True}))


def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('--check',action='store_true')
    parser.add_argument('--output-dir')
    parser.add_argument('--host',default='127.0.0.1')
    parser.add_argument('--port',type=int,default=2000)
    args=parser.parse_args()
    if args.check:check();return
    if not args.output_dir:parser.error('--output-dir is required for Native capture')
    from native_capture import run_native
    run_native(load_scene(),args.output_dir,args.host,args.port)


if __name__=='__main__':main()

"""Original CARLA capture for the straight-arrow cases.

CARLA's generic traffic-light state is retained as a source observation. It is
never promoted to a sole-arrow or lawful-presence fact without another source.
"""
import hashlib
import json
import os
import queue
import shutil
import subprocess
from pathlib import Path

from arrow_source import aspect as reviewed_aspect, bind_actor, load_binding
from map_review import validate as validate_map_review
from phase_source import entry_observation, load as load_phase_source


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def write(path, value):
    Path(path).write_text(json.dumps(value, indent=2, allow_nan=False) + '\n')


def vertices(actor):
    return [[point.x, point.y, point.z] for point in
            actor.bounding_box.get_world_vertices(actor.get_transform())]


def signal_snapshot(lights, frame, bindings=None, slot=0):
    """Retain raw actor states; a generic Green state proves no arrow shape."""
    observed=[]
    for light in lights:
        transform=light.get_transform()
        observed.append({'actor_id':int(light.id),
                         'state':str(light.get_state()),
                         'blueprint_id':str(light.type_id),
                         'position_m':[transform.location.x,transform.location.y,transform.location.z],
                         'yaw_deg':transform.rotation.yaw})
    observed.sort(key=lambda item:item['actor_id'])
    if len({item['actor_id'] for item in observed})!=len(observed):
        raise ValueError('duplicate Native traffic-light actor ID')
    if bindings:
        bound=[]
        for binding in bindings:
            match=[light for light in lights if int(light.id)==binding['packet']['actor_id']]
            if len(match)!=1:raise ValueError('reviewed arrow actor absent or duplicated')
            bind_actor(binding,match[0])
            bound.append((int(match[0].id),binding,match[0]))
        bound.sort(key=lambda row:row[0])
        if type(slot) is not int or slot<0 or slot>=len(bound):
            raise ValueError('predeclared facing head slot lacks reviewed source')
        head_id,binding,actor=bound[slot]
        return {'frame':frame,'candidate_lights':observed,'facing_head_id':head_id,
                'aspect':reviewed_aspect(binding,actor,frame),
                'reviewed_candidate_head_ids':[row[0] for row in bound]}
    return {'frame':frame,'candidate_lights':observed,
            'facing_head_id':None,
            'aspect':{'source_verified':False,'source_ref':'original CARLA actor state only',
                      'head_id':None,'observed_frame':frame,
                      'illuminated_indications':[]},
            'limitation':'CARLA actor state and blueprint ID do not establish a sole straight arrow or facing head'}


def retain_reviewed_sources(source_dir, output):
    """Copy exact reviewed packets and original assets into the attempt."""
    if not source_dir:return [],[]
    source_dir=Path(source_dir)
    if not source_dir.is_dir():raise ValueError('arrow review source directory absent')
    packets=sorted(source_dir.glob('*.json'))
    if not packets:raise ValueError('arrow review source directory contains no packets')
    destination=Path(output)/'reviewed-arrow-sources'
    destination.mkdir()
    bindings=[];names=[]
    for index,packet_path in enumerate(packets):
        packet=json.loads(packet_path.read_text())
        filename=packet.get('asset_file')
        if not isinstance(filename,str) or Path(filename).name!=filename or filename in ('','.','..'):
            raise ValueError('reviewed arrow asset filename must be local basename')
        binding=load_binding(packet_path,source_dir/filename)
        packet_copy=destination/f'head-{index}.json'
        asset_copy=destination/f'head-{index}{Path(filename).suffix}'
        shutil.copy2(packet_path,packet_copy);shutil.copy2(source_dir/filename,asset_copy)
        if sha(packet_copy)!=binding['packet_sha256'] or sha(asset_copy)!=binding['asset_sha256']:
            raise ValueError('reviewed arrow source changed during retention')
        binding['packet_path']=packet_copy;binding['asset_path']=asset_copy
        bindings.append(binding)
        names.extend([str(packet_copy.relative_to(output)),str(asset_copy.relative_to(output))])
    if len({item['packet']['actor_id'] for item in bindings})!=len(bindings):
        raise ValueError('duplicate reviewed arrow actor ID')
    return bindings,names


def retain_phase_sources(source_dir, output):
    """Retain reviewed governing phase packets and their exact source bytes."""
    if not source_dir:return {},[]
    source_dir=Path(source_dir)
    if not source_dir.is_dir():raise ValueError('participant phase source directory absent')
    destination=Path(output)/'reviewed-phase-sources';destination.mkdir()
    bindings={};names=[]
    packets=[path for path in sorted(source_dir.glob('*.json'))
             if json.loads(path.read_text()).get('format')=='c111125-reviewed-participant-phase-v1']
    if not packets:raise ValueError('participant phase review packet absent')
    for index,path in enumerate(packets):
        packet=json.loads(path.read_text())
        filename=packet.get('source_file')
        if not isinstance(filename,str) or Path(filename).name!=filename or filename in ('','.','..','review.json'):
            raise ValueError('participant phase source filename invalid')
        binding=load_phase_source(path,source_dir/filename)
        ident=packet.get('participant_slot',packet.get('participant_actor_id'))
        if ident in bindings:raise ValueError('duplicate participant phase actor ID')
        slot=destination/f'participant-{index}';slot.mkdir()
        packet_copy=slot/'review.json'
        source_copy=slot/filename
        shutil.copy2(path,packet_copy);shutil.copy2(source_dir/filename,source_copy)
        if sha(packet_copy)!=binding['packet_sha256'] or sha(source_copy)!=binding['source_sha256']:
            raise ValueError('participant phase source changed during retention')
        bindings[ident]=binding
        names.extend([str(packet_copy.relative_to(output)),str(source_copy.relative_to(output))])
    return bindings,names


def retain_map_review(source_dir, output, scene, mapping, carla):
    """Require reviewed geometry to match the live original OpenDRIVE bytes."""
    if not source_dir:raise ValueError('reviewed Native map source directory missing')
    source_dir=Path(source_dir)
    packet_path=source_dir/'review.json'
    packet=json.loads(packet_path.read_text())
    filename=packet.get('source_file')
    if not isinstance(filename,str) or Path(filename).name!=filename or filename in ('','.','..','review.json'):
        raise ValueError('reviewed map source filename invalid')
    source_path=source_dir/filename
    receipt=validate_map_review(packet_path,source_path,scene,mapping,carla)
    destination=Path(output)/'reviewed-map-source';destination.mkdir()
    shutil.copy2(packet_path,destination/'review.json')
    shutil.copy2(source_path,destination/filename)
    copied=validate_map_review(destination/'review.json',destination/filename,scene,mapping,carla)
    if copied!=receipt:raise ValueError('reviewed map changed during retention')
    return receipt,['reviewed-map-source/review.json','reviewed-map-source/'+filename]


def bind_phase_sources(bindings, actors):
    """Bind reviewed owned slots to fresh Native actor IDs and retain the join."""
    bound={};receipt=[]
    for key,binding in bindings.items():
        packet=binding['packet'];slot=packet.get('participant_slot')
        if slot is None:
            ident=packet['participant_actor_id']
            blueprint=packet.get('participant_blueprint_id')
        else:
            actor=actors.get(slot)
            if actor is None:raise ValueError('reviewed participant slot lacks owned actor')
            ident=int(actor.id);blueprint=str(actor.type_id)
            if blueprint!=packet['participant_blueprint_id']:
                raise ValueError('reviewed participant blueprint differs from spawned actor')
            if packet.get('participant_actor_id') is not None and packet['participant_actor_id']!=ident:
                raise ValueError('reviewed participant actor ID differs from spawned actor')
        if ident in bound:raise ValueError('duplicate bound participant phase actor')
        bound[ident]={**binding,'bound_actor_id':ident}
        receipt.append({'participant_actor_id':ident,'participant_slot':slot,
                        'participant_role':packet['participant_role'],
                        'participant_blueprint_id':blueprint,
                        'packet_sha256':binding['packet_sha256']})
    return bound,receipt


def apply_phase_sources(people, lights, scene, bindings, prior_inside, entry_status, frame):
    """Preserve unknown initial presence; bind later entry to raw light state."""
    from runner import overlaps
    regions=[scene['intersection_bounds_m'],*scene['adjacent_crosswalk_bounds_m']]
    current={}
    for person in people:
        ident=person['id']
        inside=any(overlaps(person['body_vertices_m'],region) for region in regions)
        current[ident]=inside
        if not inside:
            entry_status.pop(ident,None)
            continue
        binding=bindings.get(ident)
        if binding is None:continue
        observation=entry_observation(binding,person,lights,frame=frame,
                                      previous_inside=prior_inside.get(ident),inside=inside)
        person['phase_entry_observation']=observation
        if observation['reason']=='reviewed_entry_phase':
            entry_status[ident]=observation
        established=entry_status.get(ident)
        if established is not None and type(established['status']) is bool:
            person['lawfully_present']=established['status']
            person['lawful_presence_source']='reviewed-entry-phase:'+established['packet_sha256']
    for ident in tuple(entry_status):
        if ident not in current:entry_status.pop(ident,None)
    prior_inside.clear();prior_inside.update(current)
    return people


def map_context(mapping, scene, carla):
    """Check the authored straight route against actual driving waypoints."""
    points=[]
    for x in (scene['approach_x_m'],scene['stop_line_x_m'],scene['exit_x_m']):
        waypoint=mapping.get_waypoint(carla.Location(x=x,y=0,z=0))
        if waypoint is None or abs(waypoint.transform.location.x-x)>1.5 or abs(waypoint.transform.location.y)>1.5:
            raise ValueError('authored straight route lacks matching Native driving waypoint')
        points.append(waypoint)
    if len({(point.road_id,point.lane_id) for point in points})!=1:
        raise ValueError('authored straight route changes road or lane')
    return {'source':'native_map','road_id':points[0].road_id,'lane_id':points[0].lane_id,
            'stop_line_x_m':scene['stop_line_x_m'],
            'arrow_exhibition_after_s':scene['arrow_exhibition_after_s'],
            'intersection_bounds_m':scene['intersection_bounds_m'],
            'adjacent_crosswalk_bounds_m':scene['adjacent_crosswalk_bounds_m'],
            'facing_head_id':None,
            'geometry_limitation':'Authored region coordinates require Native map and visible asset review',
            'lawful_presence_source_verified':False}


def participant_inventory(world, ego):
    """Include all live vehicles and walkers, not only actors owned here."""
    candidates=[('vehicle',actor) for actor in world.get_actors().filter('vehicle.*')]
    candidates += [('pedestrian',actor) for actor in world.get_actors().filter('walker.pedestrian.*')]
    rows=[]
    for role,actor in candidates:
        if int(actor.id)==int(ego.id):continue
        rows.append({'id':int(actor.id),'role':role,'body_vertices_m':vertices(actor),
                     'blueprint_id':str(getattr(actor,'type_id','')),
                     'lawfully_present':None,'lawful_presence_source':None})
    rows.sort(key=lambda item:item['id'])
    if len({item['id'] for item in rows})!=len(rows):
        raise ValueError('duplicate Native participant actor ID')
    return rows


class CameraBank:
    SPECS=(('overview',1920,1080,(0,0,45,-90)),
           ('approach',1280,720,(-15,-12,12,-25)),
           ('reference_corner',1280,720,(4,4,12,-45)),
           ('driver_reference',1280,720,(0,0,2,0)))

    def __init__(self,world,ego,output,carla):
        self.sensors=[];self.encoders={};self.queues={};self.errors=[]
        try:self._start(world,ego,output,carla)
        except BaseException:
            try:self.close()
            except BaseException:pass
            raise

    def _start(self,world,ego,output,carla):
        library=world.get_blueprint_library()
        for name,width,height,pose in self.SPECS:
            blueprint=library.find('sensor.camera.rgb')
            blueprint.set_attribute('image_size_x',str(width))
            blueprint.set_attribute('image_size_y',str(height))
            blueprint.set_attribute('fov','90')
            x,y,z,pitch=pose
            transform=carla.Transform(carla.Location(x=x,y=y,z=z),carla.Rotation(pitch=pitch))
            sensor=world.spawn_actor(blueprint,transform,attach_to=ego if name=='driver_reference' else None)
            self.sensors.append(sensor)
            frames=queue.Queue(maxsize=4);self.queues[name]=frames
            def receive(image,q=frames,label=name):
                try:q.put_nowait(image)
                except queue.Full:self.errors.append('camera queue overflow: '+label)
            sensor.listen(receive)
            command=['ffmpeg','-nostdin','-hide_banner','-loglevel','error','-n',
                     '-f','rawvideo','-pixel_format','bgra','-video_size',f'{width}x{height}',
                     '-framerate','20','-i','pipe:0','-an','-c:v','ffv1','-pix_fmt','bgra',
                     str(output/(name+'.mkv'))]
            self.encoders[name]=subprocess.Popen(command,stdin=subprocess.PIPE,stderr=subprocess.DEVNULL)

    def append(self,frame):
        if self.errors:raise RuntimeError('; '.join(self.errors))
        for name,_,_,_ in self.SPECS:
            image=self.queues[name].get(timeout=15)
            if image.frame!=frame:raise RuntimeError(f'{name} camera frame differs from world frame')
            self.encoders[name].stdin.write(image.raw_data)

    def close(self):
        failures=[]
        for sensor in reversed(self.sensors):
            try:sensor.stop()
            except BaseException as exc:failures.append(repr(exc))
        for name,process in self.encoders.items():
            try:
                if process.stdin and not process.stdin.closed:process.stdin.close()
                if process.wait(timeout=180)!=0:failures.append('camera encoder failed: '+name)
            except BaseException as exc:failures.append(repr(exc))
        for sensor in reversed(self.sensors):
            try:sensor.destroy()
            except BaseException as exc:failures.append(repr(exc))
        if failures:raise RuntimeError('; '.join(failures))


